{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table maplemonk.saadaa_refund_management as with discount_percent as ( select distinct discount_codes, case when lower(discount_codes) like any (\'%buy4%\',\'%buy 4%\',\'%shop 4%\',\'%shop4%\',\'%shop any 4%\',\'%buy any 4%\',\'%4 pants%\',\'%4pala%\',\'%4pant%\',\'%4cotton%\') then 0.25 when lower(discount_codes) like any (\'%buy3%\',\'%buy 3%\',\'%shop 3%\',\'%shop3%\',\'%shop any 3%\',\'%buy any 3%\',\'%3 pants%\',\'%3pala%\',\'%3pant%\',\'%3cotton%\') then 0.20 when lower(discount_codes) like any (\'%buy2%\',\'%buy 2%\',\'%shop 2%\',\'%shop2%\',\'%shop any 2%\',\'%buy any 2%\',\'%2 pants%\',\'%2pala%\',\'%2pant%\',\'%2cotton%\') then 0.15 when not(lower(discount_codes) like \'%nector%\') then 0.15 else null end as discount_percent from maplemonk.saadaa_returns_consolidated ), retained_orders as ( select reference_code, case when lower(discount_codes) like any (\'%rahosaadaa%\',\'%raho saadaa%\',\'%pehnosaadaa%\',\'%pehno saadaa%\') then 0.15 else 0 end as fixed_discount_percent, sum(case when return_flag = 0 or (return_flag = 1 and return_request_type = \'exchange\') then total_sales end) as retained_products_value, sum(case when return_flag = 0 or (return_flag = 1 and return_request_type = \'exchange\') then order_quantity end) as retained_products_count, sum(case when (return_flag = 1 and return_request_type = \'return\') then total_sales end) as returned_products_value, sum(case when (return_flag = 1 and return_request_type = \'return\') then mrp * ifnull(TOTAL_RETURNED_QUANTITY,0) end) as returned_products_mrp, sum(ifnull(total_refund_amount,0)) total_refund_amount, case when min(mrp) = 499 then ARRAY_AGG(mrp ORDER BY mrp ASC LIMIT 2)[SAFE_OFFSET(1)] else min(mrp) end as least_order_mrp, case when min(mrp) = 499 then ARRAY_AGG(mrp ORDER BY mrp ASC LIMIT 3)[SAFE_OFFSET(2)] else ARRAY_AGG(mrp ORDER BY mrp ASC LIMIT 2)[SAFE_OFFSET(1)] end as second_least_mrp, case when min(mrp) = 499 then ARRAY_AGG(mrp ORDER BY mrp ASC LIMIT 4)[SAFE_OFFSET(3)] else ARRAY_AGG(mrp ORDER BY mrp ASC LIMIT 3)[SAFE_OFFSET(2)] end as third_least_mrp, case when min(mrp) = 499 then ARRAY_AGG(mrp ORDER BY mrp ASC LIMIT 5)[SAFE_OFFSET(4)] else ARRAY_AGG(mrp ORDER BY mrp ASC LIMIT 4)[SAFE_OFFSET(3)] end as fourth_least_mrp, case when min(mrp) = 499 then ARRAY_AGG(mrp ORDER BY mrp ASC LIMIT 6)[SAFE_OFFSET(5)] else ARRAY_AGG(mrp ORDER BY mrp ASC LIMIT 5)[SAFE_OFFSET(4)] end as fifth_least_mrp, case when min(mrp) = 499 then ARRAY_AGG(mrp ORDER BY mrp ASC LIMIT 7)[SAFE_OFFSET(6)] else ARRAY_AGG(mrp ORDER BY mrp ASC LIMIT 6)[SAFE_OFFSET(5)] end as sixth_least_mrp, case when min(mrp) = 499 then ARRAY_AGG(mrp ORDER BY mrp ASC LIMIT 8)[SAFE_OFFSET(7)] else ARRAY_AGG(mrp ORDER BY mrp ASC LIMIT 7)[SAFE_OFFSET(6)] end as seventh_least_mrp, sum(discount) as total_discount_on_order from maplemonk.saadaa_returns_consolidated group by 1,2 ), returned_orders as ( select r.reference_code as order_name, date(order_date) order_date, payment_mode, date(final_return_request_date) return_request_date, awb as forward_awb, return_awb as reverse_awb, concat(r.reference_code,return_awb) as unique_key, phone as customer_phone, customer_name, quantity_count as order_quantity, return_quantity_count, fixed_discount_percent, total_order_value, total_discount_value, r.total_mrp_value - rp.returned_products_mrp as original_retained_product_price, rp.returned_products_mrp as returned_product_mrp, r.mrp, r.total_mrp_value, r.discount_codes, rp.total_refund_amount, rp.least_order_mrp, rp.second_least_mrp, rp.third_least_mrp, rp.fourth_least_mrp, rp.fifth_least_mrp, rp.sixth_least_mrp, rp.seventh_least_mrp, rp.total_discount_on_order, r.discount, retained_products_count, dp.discount_percent, case when r.estimated_pickup_date is not null then \'Pickup Done\' else \'Pickup Not Done\' end as Pickup_Flag, rp.retained_products_value, case when dp.discount_percent is not null then ( case when dp.discount_percent = 0.25 and (quantity_count - return_quantity_count) >= 4 then 0.25 when dp.discount_percent = 0.25 and (quantity_count - return_quantity_count) = 3 and date(final_return_request_date) < \'2025-07-10\' then 0.20 when dp.discount_percent = 0.25 and (quantity_count - return_quantity_count) >= 2 then 0.15 when dp.discount_percent = 0.20 and (quantity_count - return_quantity_count) >= 2 then 0.15 when dp.discount_percent = 0.15 and (quantity_count - return_quantity_count) >= 2 then 0.15 else 0 end ) else 0 end as new_discount_percent, returned_products_value, nector_coins_spent from maplemonk.saadaa_returns_consolidated r left join discount_percent dp on dp.discount_codes = r.discount_codes left join retained_orders rp on rp.reference_code = r.reference_code where lower(return_request_type) = \'return\' and lower(marketplace) like \'%website%\' and return_flag = 1 ) select *, case when discount_codes = \'B3G1\' and (order_quantity - return_quantity_count) >= 28 then (total_order_value - (ifnull(original_retained_product_price,0) - least((least_order_mrp + second_least_mrp + third_least_mrp+ fourth_least_mrp + fifth_least_mrp + sixth_least_mrp + seventh_least_mrp),total_discount_on_order))) when discount_codes = \'B3G1\' and (order_quantity - return_quantity_count) >= 24 then (total_order_value - (ifnull(original_retained_product_price,0) - least((least_order_mrp + second_least_mrp + third_least_mrp+ fourth_least_mrp + fifth_least_mrp + sixth_least_mrp),total_discount_on_order))) when discount_codes = \'B3G1\' and (order_quantity - return_quantity_count) >= 20 then (total_order_value - (ifnull(original_retained_product_price,0) - least((least_order_mrp + second_least_mrp + third_least_mrp+ fourth_least_mrp + fifth_least_mrp),total_discount_on_order))) when discount_codes = \'B3G1\' and (order_quantity - return_quantity_count) >= 16 then (total_order_value - (ifnull(original_retained_product_price,0) - least((least_order_mrp + second_least_mrp + third_least_mrp + fourth_least_mrp),total_discount_on_order))) when discount_codes = \'B3G1\' and (order_quantity - return_quantity_count) >= 12 then (total_order_value - (ifnull(original_retained_product_price,0) - least((least_order_mrp + second_least_mrp + third_least_mrp),total_discount_on_order))) when discount_codes = \'B3G1\' and (order_quantity - return_quantity_count) >= 8 then (total_order_value - (ifnull(original_retained_product_price,0) - least((least_order_mrp + second_least_mrp),total_discount_on_order))) when discount_codes = \'B3G1\' and (order_quantity - return_quantity_count) > 3 then (total_order_value - (ifnull(original_retained_product_price,0) - least(least_order_mrp,total_discount_on_order))) else total_order_value - (ifnull(original_retained_product_price,0) * (1-new_discount_percent)) end as final_cash_refund, case when ifnull(nector_coins_spent,0) <= 0 then (case when (original_retained_product_price * (1- coalesce(nullif(new_discount_percent,0),ifnull(fixed_discount_percent,0)))) < 0 then 0 else (original_retained_product_price * (1- coalesce(nullif(new_discount_percent,0),ifnull(fixed_discount_percent,0)))) end) else (case when (original_retained_product_price - nector_coins_spent) < 0 then 0 else (original_retained_product_price - nector_coins_spent) end) end as actual_refund_amount, case when greatest(original_retained_product_price * (1- coalesce(nullif(new_discount_percent,0), ifnull(fixed_discount_percent,0))) - nector_coins_spent, 0) > 0 then 0 else nector_coins_spent - (original_retained_product_price * (1- coalesce(nullif(new_discount_percent,0), ifnull(fixed_discount_percent,0)))) end as remaining_nector_coins from returned_orders qualify row_number() over (partition by order_name,reverse_awb order by return_request_date desc) = 1;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            